        { k = "turnin", t = "Turn in Find OOX-22/FE! to Homing Robot OOX-22/FE", q = 2766, n = "Homing Robot OOX-22/FE", e = "npc", id = 7807, m = 1444, x = 53.35, y = 55.7, nt = { { l = 2, t = "The robot waits just past the first part of the yeti cave, in a small clearing before the next cave: kill the yetis on the way in, they respawn quickly." }, { l = 2, t = "Both of you must hand in Find OOX-22/FE! before either of you accepts the escort, or the second one can't join it." } }, lvl = 45 },
