        { k = "objective", t = "Escort OOX-22/FE to the dock on the Forgotten Coast", q = 2767, o = 1, ic = "text", m = 1444, x = 45.6, y = 43.4, nt = { { l = 2, t = "Start the escort only when both of you have the quest. It is hard: three ambushes come along the way. Three yetis (46) just outside the cave before the road, three gorillas (43) after the robot turns north on the main road, then four gnolls (41-43, one a caster) at the fork after the stone bridge by a waterfall. Save your long cooldowns for the gnolls." }, { l = 2, t = "Let the robot take a hit before you pull everything off it, or it keeps walking and leaves you fighting behind. If it doesn't move at all, another player is escorting it: wait for it to come back." }, { l = 2, t = "Players on WoW Forever have reported the robot refusing the escort (\"You don't meet the requirements\"). If that happens, skip the escort and its turn-in in Booty Bay." } }, lvl = 45 },
